/* Sohoz Karbar Tech Solutions — License Sales Agreement & Delivery Acknowledgement */
(function(){
'use strict';
if(window.LicenseAgreement)return;
const SKA_LOGO="data:image/png;base64,";
const COMPANY='Sohoz Karbar Tech Solutions', PHONE='+8801625914562', EMAIL='rifat4440@gmail.com';
const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const money=n=>'৳'+Number(n||0).toLocaleString('en-BD',{maximumFractionDigits:2});
const dateValue=ts=>{const d=ts?new Date(Number(ts)):new Date();return isNaN(d)?'':d.toISOString().slice(0,10)};
const longDate=s=>{try{return new Date(s+'T00:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'})}catch(e){return s}};
const agreementNo=lic=>{let k=String(lic?.key||lic?.id||Date.now()).replace(/[^A-Z0-9]/gi,'').slice(-8).toUpperCase();return 'SKA-'+new Date().toISOString().slice(0,10).replace(/-/g,'')+'-'+k};
function term(lic){if(String(lic?.months)==='lifetime'||Number(lic?.expiresAt)>=4102444800000)return 'Lifetime';if(lic?.licenseType==='trial')return (lic.trialDays||3)+' Days Trial';return (lic?.months||12)+' Months'}
function suggestedPrice(lic){let m=String(lic?.months||'');return m==='12'?19999:m==='24'?35000:m==='lifetime'?50000:0}
function css(){return `
#skAgrMask{position:fixed;inset:0;z-index:100250;background:rgba(2,6,23,.82);padding:18px;overflow:auto;font-family:Inter,Arial,sans-serif}.skAgrBox{max-width:980px;margin:auto;background:#fff;border-radius:18px;box-shadow:0 30px 80px #0008;overflow:hidden}.skAgrHead{padding:18px 22px;background:linear-gradient(135deg,#073b32,#0e7a4f);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:15px}.skAgrHead h2{margin:0;font-size:20px}.skAgrHead p{margin:4px 0 0;font-size:12px;opacity:.85}.skAgrClose{border:0;background:#fff;color:#0f172a;border-radius:10px;width:38px;height:38px;font-size:20px;cursor:pointer}.skAgrForm{padding:20px}.skAgrGrid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.skAgrField{display:flex;flex-direction:column;gap:5px}.skAgrField.w2{grid-column:span 2}.skAgrField.all{grid-column:1/-1}.skAgrField label{font-size:11px;font-weight:800;color:#475569;text-transform:uppercase;letter-spacing:.35px}.skAgrField input,.skAgrField select,.skAgrField textarea{width:100%;box-sizing:border-box;border:1px solid #cbd5e1;border-radius:9px;padding:10px 11px;background:#fff;color:#0f172a;font:inherit}.skAgrField textarea{min-height:66px;resize:vertical}.skAgrNote{margin:14px 0;padding:11px 13px;background:#eff6ff;border:1px solid #bfdbfe;border-radius:10px;color:#1e3a8a;font-size:12px;line-height:1.55}.skAgrActions{display:flex;justify-content:flex-end;gap:9px;flex-wrap:wrap;margin-top:16px}.skAgrActions button{border:0;border-radius:9px;padding:10px 16px;font-weight:800;cursor:pointer}.skAgrPreview{background:#e2e8f0;color:#0f172a}.skAgrPrint{background:#0e7a4f;color:#fff}.skAgrSave{background:#d97706;color:#fff}.skAgrFab{position:fixed;right:16px;bottom:76px;z-index:10070;border:0;border-radius:999px;padding:10px 16px;background:linear-gradient(135deg,#0f766e,#16a34a);color:#fff;font-weight:800;box-shadow:0 10px 25px #064e3b55;cursor:pointer}.skAgrSelect{margin-bottom:14px;padding:12px;background:#f8fafc;border:1px solid #e2e8f0;border-radius:10px}@media(max-width:720px){.skAgrGrid{grid-template-columns:1fr 1fr}.skAgrField.w2{grid-column:span 2}}@media(max-width:480px){#skAgrMask{padding:0}.skAgrBox{border-radius:0;min-height:100%}.skAgrGrid{grid-template-columns:1fr}.skAgrField.w2,.skAgrField.all{grid-column:1}.skAgrFab{right:10px;bottom:70px;padding:9px 12px;font-size:12px}}
`}
function getForm(root){let val=id=>$('#'+id,root)?.value||'';return{agreementNo:val('ska_no'),agreementDate:val('ska_date'),customerName:val('ska_customer'),businessName:val('ska_business'),mobile:val('ska_mobile'),address:val('ska_address'),nid:val('ska_nid'),sellerName:val('ska_seller'),sellerMobile:val('ska_seller_mobile'),licenseKey:val('ska_key'),plan:val('ska_plan'),term:val('ska_term'),expires:val('ska_expires'),maxDevices:val('ska_devices'),price:Number(val('ska_price')||0),discount:Number(val('ska_discount')||0),paid:Number(val('ska_paid')||0),support:val('ska_support'),deliveryStatus:val('ska_delivery'),notes:val('ska_notes'),createdAt:Date.now(),documentType:'license-sales-agreement'} }
/* ---- owner-controlled settings (Workstation writes these) ---- */
var SKA_SETTINGS=null;
function skaDefaults(){return {autoPrint:true, extraTerms:'', supportDefault:'As per selected plan'};}
function skaGetSettings(){
  if(SKA_SETTINGS)return SKA_SETTINGS;
  var s=skaDefaults();
  try{var l=JSON.parse(localStorage.getItem('sk_agreement_settings')||'null');if(l)SKA_MERGE(s,l);}catch(e){}
  SKA_SETTINGS=s;
  // async pull from Firestore (license_customers/_ws_agreement_settings)
  skaPullSettings();
  return s;
}
function SKA_MERGE(base,over){for(var k in over){if(over[k]!==undefined&&over[k]!==null)base[k]=over[k];}return base;}
function skaSaveSettings(obj){
  SKA_SETTINGS=SKA_MERGE(skaDefaults(),obj||{});
  try{localStorage.setItem('sk_agreement_settings',JSON.stringify(SKA_SETTINGS));}catch(e){}
  return SKA_SETTINGS;
}
async function skaPullSettings(){
  try{
    var fb=window.LicenseFirebaseService&&window.LicenseFirebaseService.getDb?window.LicenseFirebaseService.getDb()
          :(window.FirebaseService&&window.FirebaseService.db?window.FirebaseService.db:null);
    var snap=null;
    if(fb&&fb.collection){snap=await fb.collection('license_customers').doc('_ws_agreement_settings').get().catch(()=>null);}
    if(snap&&snap.exists&&snap.data){SKA_MERGE(SKA_SETTINGS||(SKA_SETTINGS=skaDefaults()),snap.data());try{localStorage.setItem('sk_agreement_settings',JSON.stringify(SKA_SETTINGS));}catch(e){}}
  }catch(e){/* offline / no db — keep local settings */}
}
function printHTML(d){let net=Math.max(0,d.price-d.discount),due=Math.max(0,net-d.paid),delivered=d.deliveryStatus==='delivered';const copy=label=>`<section class="page"><header><img class="logo" src="${SKA_LOGO}" alt="logo"><div><h1>${COMPANY}</h1><p>Simple Technology. Smarter Business.</p></div><b class="copy">${label}</b></header><div class="title"><h2>SOFTWARE LICENSE SALES AGREEMENT</h2><h3>সফটওয়্যার লাইসেন্স বিক্রয় চুক্তিপত্র</h3><p>Agreement No: <b>${esc(d.agreementNo)}</b> &nbsp;|&nbsp; Date: <b>${esc(longDate(d.agreementDate))}</b></p></div><p class="intro">এই চুক্তি <b>${COMPANY}</b> (“Provider”) এবং নিচে উল্লেখিত গ্রাহক (“Customer”)-এর মধ্যে SohozKarbar ERP ব্যবহারের লাইসেন্স, মূল্য, সেবা ও দায়বদ্ধতা সম্পর্কে সম্পাদিত হলো।</p><table class="info"><tr><th>Customer / গ্রাহক</th><td>${esc(d.customerName)}</td><th>Business</th><td>${esc(d.businessName||'—')}</td></tr><tr><th>Mobile</th><td>${esc(d.mobile||'—')}</td><th>NID (Optional)</th><td>${esc(d.nid||'—')}</td></tr><tr><th>Address</th><td colspan="3">${esc(d.address||'—')}</td></tr><tr><th>Sales Representative</th><td>${esc(d.sellerName||'Direct Sale')}</td><th>Seller Mobile</th><td>${esc(d.sellerMobile||'—')}</td></tr></table><h4>LICENSE DELIVERY / লাইসেন্স হস্তান্তর</h4><table class="license"><tr><th>Product</th><td>SohozKarbar ERP</td><th>Plan</th><td>${esc(d.plan)}</td></tr><tr><th>License Key</th><td colspan="3" class="key">${esc(d.licenseKey||'PENDING')}</td></tr><tr><th>Term</th><td>${esc(d.term)}</td><th>Device Limit</th><td>${esc(d.maxDevices||'1')} device(s)</td></tr><tr><th>Expiry</th><td>${esc(d.expires?longDate(d.expires):d.term==='Lifetime'?'No Expiry':'—')}</td><th>Status</th><td><b>${delivered?'DELIVERED & RECEIVED':'PENDING DELIVERY'}</b></td></tr><tr><th>Access</th><td colspan="3">https://www.sohozkarbar.pro.bd/erp &nbsp; • &nbsp; Initial login: Admin / 123456 (change after first login)</td></tr></table><h4>PAYMENT / মূল্য ও পরিশোধ</h4><div class="pay"><span>List Price <b>${money(d.price)}</b></span><span>Discount <b>${money(d.discount)}</b></span><span>Net Price <b>${money(net)}</b></span><span>Paid <b>${money(d.paid)}</b></span><span>Due <b>${money(due)}</b></span></div><h4>TERMS & CONDITIONS / শর্তাবলি</h4><ol><li>লাইসেন্সটি নির্ধারিত গ্রাহক ও ব্যবসার জন্য সীমিত, non-transferable এবং পুনর্বিক্রয়যোগ্য নয়।</li><li>লাইসেন্স key, account বা software অন্য ব্যক্তি/প্রতিষ্ঠানের সঙ্গে অননুমোদিতভাবে share, copy, reverse-engineer বা misuse করা যাবে না।</li><li>নির্ধারিত device limit ও মেয়াদ প্রযোজ্য। অতিরিক্ত device, customization, data migration ও বিশেষ integration আলাদা charge-এর আওতায় আসতে পারে।</li><li>Customer নিজের entry, password, user access, source documents এবং নিয়মিত backup-এর দায়িত্ব নেবেন। Provider যুক্তিসঙ্গত technical support দেবে; internet, device বা third-party cloud outage Provider-এর নিয়ন্ত্রণের বাইরে।</li><li>Support period: <b>${esc(d.support||(SKA_SETTINGS&&SKA_SETTINGS.supportDefault)||'As per selected plan')}</b>. Training/support সময় ও scope পারস্পরিক সম্মতিতে নির্ধারিত হবে।</li><li>Activation ও license delivery-এর পর fee সাধারণত non-refundable; তবে প্রমাণিত technical failure বা উভয় পক্ষের লিখিত সম্মতিতে সমাধান/সমন্বয় করা যাবে।</li><li>বকেয়া, fraud, illegal use বা শর্ত ভঙ্গ হলে পূর্ব নোটিশসহ license সীমিত/স্থগিত করা যেতে পারে। Customer-এর বৈধ business data ইচ্ছাকৃতভাবে দখল করা হবে না।</li><li>বিরোধ হলে প্রথমে আলোচনার মাধ্যমে সমাধান করা হবে; প্রযোজ্য ক্ষেত্রে বাংলাদেশের আইন অনুসরণ করা হবে।</li>${((d.extraTerms||(SKA_SETTINGS&&SKA_SETTINGS.extraTerms)||'').split(/\n+/).filter(Boolean).map(t=>'<li>'+esc(t)+'</li>').join(''))}</ol>${d.notes?`<div class="notes"><b>Special Notes:</b> ${esc(d.notes)}</div>`:''}<div class="ack">☐ আমি উপরের license key, access information ও service terms বুঝে গ্রহণ করেছি। / I acknowledge receipt of the license and accept these terms.</div><div class="sign"><div><span>Customer Signature</span><small>Name: ${esc(d.customerName)}<br>Date:</small></div><div><span>Sales Representative</span><small>Name: ${esc(d.sellerName||'Direct Sale')}<br>Date:</small></div><div><span>Authorized Signature</span><small>For ${COMPANY}<br>Date:</small></div><div><span>Witness</span><small>Name & Mobile:<br>Date:</small></div></div><footer>${PHONE} • ${EMAIL} • www.sohozkarbar.pro.bd<br><small>This operational agreement template may be reviewed by a qualified lawyer for a specific transaction.</small></footer></section>`;return `<!doctype html><html><head><meta charset="utf-8"><title>${esc(d.agreementNo)} — License Agreement</title><style>@page{size:A4;margin:10mm}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}html,body{margin:0;background:#dbe4ea;color:#111827;font-family:Arial,"Noto Sans Bengali",sans-serif}.page{width:190mm;min-height:277mm;margin:10px auto;background:white;padding:10mm;page-break-after:always}.page:last-child{page-break-after:auto}header{display:flex;align-items:center;border-bottom:3px solid #0e7a4f;padding-bottom:8px}.logo{width:46px;height:46px;border-radius:8px;object-fit:contain;margin-right:10px;-webkit-print-color-adjust:exact;print-color-adjust:exact}header h1{font-size:17px;margin:0}header p{font-size:9px;margin:2px 0}.copy{margin-left:auto;border:1px solid #94a3b8;padding:5px 8px;font-size:9px}.title{text-align:center;margin:9px 0}.title h2{font-size:16px;margin:0}.title h3{font-size:14px;margin:3px}.title p,.intro{font-size:9.5px;line-height:1.45}h4{font-size:10px;color:#0e7a4f;border-bottom:1px solid #bbf7d0;margin:8px 0 4px;padding-bottom:2px}.info,.license{border-collapse:collapse;width:100%;font-size:9px}.info th,.info td,.license th,.license td{border:1px solid #cbd5e1;padding:4px 5px;text-align:left}.info th,.license th{background:#f1f5f9;width:16%}.key{font-family:monospace;font-size:12px;font-weight:900;letter-spacing:.7px;color:#0f766e}.pay{display:grid;grid-template-columns:repeat(5,1fr);gap:5px}.pay span{border:1px solid #cbd5e1;border-radius:5px;padding:5px;font-size:8.5px}.pay b{display:block;font-size:10px;margin-top:2px}ol{margin:4px 0 6px;padding-left:18px;font-size:8.7px;line-height:1.42}li{margin:2px 0}.notes,.ack{font-size:8.8px;border:1px solid #cbd5e1;padding:5px;margin:5px 0}.ack{background:#f0fdf4;border-color:#86efac}.sign{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-top:18px}.sign div{border-top:1px solid #111;text-align:center;padding-top:3px;min-height:38px}.sign span{font-size:8.5px;font-weight:700}.sign small{display:block;font-size:7px;line-height:1.5;margin-top:3px}footer{text-align:center;border-top:1px solid #cbd5e1;padding-top:5px;margin-top:7px;font-size:8px;color:#475569}footer small{font-size:6.8px}.toolbar{position:sticky;top:0;z-index:50;display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap;background:#0e7a4f;color:#fff;padding:10px 12px;font-family:Arial,\"Noto Sans Bengali\",sans-serif}.toolbar b{font-size:13px}.toolbar button{border:0;border-radius:8px;padding:10px 18px;font-size:14px;font-weight:800;cursor:pointer;background:#fff;color:#0e7a4f}.toolbar .hint{font-size:11px;opacity:.9;width:100%;text-align:center}@media print{body{background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact}.page{margin:0;box-shadow:none;-webkit-print-color-adjust:exact;print-color-adjust:exact}.toolbar{display:none}h4,.key,.ack,.info th,.license th{print-color-adjust:exact;-webkit-print-color-adjust:exact}}@media screen and (max-width:800px){.page{width:190mm;transform-origin:top left;transform:scale(.48);margin-bottom:-140mm}}</style></head><body><div class=\"toolbar\" id=\"skBar\"><b>🖨️ License Agreement ready — 2 copies (Company + Customer)</b><button onclick=\"window.print()\">Print / Save as PDF</button><span class=\"hint\">If the print preview looks empty, tap this button again after the page fully loads — both copies will print.</span></div>${copy('COMPANY COPY')}${copy('CUSTOMER COPY')}<script>(function(){function ready(){return document.readyState==='complete'&&document.querySelectorAll('section.page').length>=2&&document.body.innerText.length>500;}var n=0;function go(){try{window.focus();}catch(e){}try{window.print();}catch(e){}}function tick(){if(ready()){setTimeout(go,150);}else if(n<60){n++;setTimeout(tick,150);}else{var b=document.getElementById('skBar');if(b)b.scrollIntoView();}}if(document.readyState==='complete'){tick();}else{window.addEventListener('load',function(){setTimeout(tick,100);});}})();<\/script></body></html>`}
function fill(root,lic){const set=(id,v)=>{let e=$('#'+id,root);if(e)e.value=v==null?'':v};set('ska_no',agreementNo(lic));set('ska_customer',lic?.customerName||'');set('ska_business',lic?.businessName||'');set('ska_mobile',lic?.mobile||'');set('ska_key',lic?.key||'');set('ska_plan',lic?.plan||'Standard');set('ska_term',term(lic));set('ska_expires',dateValue(lic?.expiresAt));set('ska_devices',lic?.maxDevices||1);set('ska_price',suggestedPrice(lic));set('ska_paid',suggestedPrice(lic));set('ska_delivery',lic?.key?'delivered':'pending')}
async function save(d){try{if(window.FirebaseService&&typeof FirebaseService.add==='function'){await FirebaseService.add('license_agreements',d);return true}}catch(e){console.warn('Agreement save skipped:',e)}try{localStorage.setItem('sk_agreement_'+d.agreementNo,JSON.stringify(d));return true}catch(e){return false}}
function doPrint(d){
  var st=skaGetSettings();
  var html=printHTML(d);
  // --- PRIMARY: same-document hidden iframe print (reliable on Android
  //     WebView / PWA where printing from a popped-up window can show blank).
  //     This is the same proven approach the ERP KOT/invoice slip uses.
  var printed=false;
  try{
    var old=document.getElementById('skAgrPrintFrame');if(old)old.parentNode.removeChild(old);
    var f=document.createElement('iframe');
    f.id='skAgrPrintFrame';
    f.setAttribute('aria-hidden','true');
    f.style.cssText='position:fixed;left:0;bottom:0;width:210mm;height:297mm;border:0;opacity:0;pointer-events:none;z-index:-1;';
    document.body.appendChild(f);
    var win=f.contentWindow,doc=f.contentDocument||(win&&win.document);
    var cleanup=function(){setTimeout(function(){if(f.parentNode)f.parentNode.removeChild(f);},3000);};
    var fire=function(){
      if(printed)return;printed=true;
      try{
        win.focus();
        if(!st.autoPrint){cleanup();return;} // owner turned auto-print off: leave preview; user prints from toolbar
        win.print();
      }catch(e){try{window.print();}catch(e2){}}
      cleanup();
    };
    doc.open();doc.write(html);doc.close();
    // wait until both copies are laid out, then print (fonts already same-origin;
    // give the engine a couple of frames to paint).
    var tries=0;
    var wait=function(){
      var pages=doc.querySelectorAll('section.page');
      var ready=doc.readyState==='complete'&&pages.length>=2&&doc.body&&doc.body.innerText&&doc.body.innerText.length>500;
      if(ready){setTimeout(fire,120);}
      else if(tries++<60){setTimeout(wait,100);}
      else{fire();}
    };
    if(doc.readyState==='complete')setTimeout(wait,60);else{win.addEventListener('load',function(){setTimeout(wait,60);});setTimeout(wait,800);}
    return true;
  }catch(err){
    // --- FALLBACK: classic popup window if iframe print is unavailable ---
    try{
      var w=window.open('','_blank');
      if(!w){alert('Print could not start automatically. Please tap the green Print / Save as PDF button to print the agreement.');return false;}
      w.document.open();w.document.write(html);w.document.close();
      try{w.focus();}catch(e){}
      return true;
    }catch(e2){alert('Could not open the print view. Please try again or use a desktop browser.');return false;}
  }
}
async function open(selected){document.querySelector('#skAgrMask')?.remove();let all=[];if(!selected&&window.License?.getAllLicenses){try{all=await License.getAllLicenses()}catch(e){}}let lic=selected||window.License?.getLicense?.()||all[0]||{};let mask=document.createElement('div');mask.id='skAgrMask';mask.innerHTML=`<style>${css()}</style><div class="skAgrBox"><div class="skAgrHead"><div><h2>License Sales Agreement</h2><p>Print two signature-ready copies with license delivery acknowledgement</p></div><button class="skAgrClose" aria-label="Close">×</button></div><div class="skAgrForm">${all.length?`<div class="skAgrSelect"><label style="font-size:11px;font-weight:800">SELECT EXISTING LICENSE</label><select id="ska_pick" style="width:100%;margin-top:5px;padding:9px;border:1px solid #cbd5e1;border-radius:8px">${all.map((x,i)=>`<option value="${i}">${esc(x.customerName||'Customer')} — ${esc(x.key||'No key')}</option>`).join('')}</select></div>`:''}<div class="skAgrGrid"><div class="skAgrField"><label>Agreement Number</label><input id="ska_no"></div><div class="skAgrField"><label>Agreement Date</label><input id="ska_date" type="date" value="${dateValue()}"></div><div class="skAgrField"><label>Delivery Status</label><select id="ska_delivery"><option value="delivered">License Delivered</option><option value="pending">Pending Delivery</option></select></div><div class="skAgrField"><label>Customer Name *</label><input id="ska_customer"></div><div class="skAgrField"><label>Business Name</label><input id="ska_business"></div><div class="skAgrField"><label>Mobile</label><input id="ska_mobile"></div><div class="skAgrField w2"><label>Customer Address</label><input id="ska_address"></div><div class="skAgrField"><label>NID (Optional)</label><input id="ska_nid"></div><div class="skAgrField"><label>Sales Representative</label><input id="ska_seller" placeholder="Direct Sale / Seller name"></div><div class="skAgrField"><label>Seller Mobile</label><input id="ska_seller_mobile"></div><div class="skAgrField"><label>Support Period</label><input id="ska_support" value="12 months standard support"></div><div class="skAgrField w2"><label>License Key *</label><input id="ska_key" style="font-family:monospace;font-weight:800"></div><div class="skAgrField"><label>Plan</label><input id="ska_plan"></div><div class="skAgrField"><label>License Term</label><input id="ska_term"></div><div class="skAgrField"><label>Expiry Date</label><input id="ska_expires" type="date"></div><div class="skAgrField"><label>Device Limit</label><input id="ska_devices" type="number" min="1" value="1"></div><div class="skAgrField"><label>List Price</label><input id="ska_price" type="number" min="0"></div><div class="skAgrField"><label>Discount</label><input id="ska_discount" type="number" min="0" value="0"></div><div class="skAgrField"><label>Paid Amount</label><input id="ska_paid" type="number" min="0"></div><div class="skAgrField all"><label>Special Notes / Additional Scope</label><textarea id="ska_notes" placeholder="Training, customization, installment or other agreed terms..."></textarea></div></div><div class="skAgrNote">The printed document includes company and customer copies, payment details, license key, delivery acknowledgement, fair-use terms and signature spaces. NID is optional. Saved records go to the signed-in tenant's <b>license_agreements</b> collection, not a customer root document.</div><div class="skAgrActions"><button class="skAgrPreview" id="ska_print">Print Without Saving</button><button class="skAgrSave" id="ska_save">Save & Print Agreement</button></div></div></div>`;document.body.appendChild(mask);fill(mask,lic);$('.skAgrClose',mask).onclick=()=>mask.remove();mask.onclick=e=>{if(e.target===mask)mask.remove()};$('#ska_pick',mask)?.addEventListener('change',e=>fill(mask,all[Number(e.target.value)]));$('#ska_print',mask).onclick=()=>{let d=getForm(mask);if(!d.customerName)return alert('Customer name is required.');doPrint(d)};$('#ska_save',mask).onclick=async e=>{let d=getForm(mask);if(!d.customerName||!d.licenseKey)return alert('Customer name and license key are required.');let b=e.currentTarget,o=b.textContent;b.disabled=true;b.textContent='Saving…';let ok=await save(d);b.disabled=false;b.textContent=o;if(ok){try{window.UI?.toast?.('Agreement saved. Print window opened.','success')}catch(x){}doPrint(d)}else alert('Could not save. Use Print Without Saving.')};}
function canShow(){try{return window.APP_CONFIG?.buildType==='admin'||window.AuthService?.isSuperAdmin?.()||window.AuthService?.hasRole?.('admin')||String(window.AuthService?.currentUser?.username||'').toLowerCase()==='rifat'}catch(e){return false}}
function addFab(){if(!document.body||document.querySelector('#skAgrFab')||!canShow())return;let b=document.createElement('button');b.id='skAgrFab';b.className='skAgrFab';b.textContent='📄 License Agreement';b.onclick=()=>open();document.body.appendChild(b)}
window.LicenseAgreement={open,print:doPrint,save,
  getSettings:skaGetSettings,
  setSettings:function(obj){var s=skaSaveSettings(obj);
    // best-effort Firestore sync when a signed-in db handle is available
    try{var fb=window.LicenseFirebaseService&&window.LicenseFirebaseService.getDb?window.LicenseFirebaseService.getDb():(window.FirebaseService&&window.FirebaseService.db?window.FirebaseService.db:null);
      if(fb&&fb.collection){fb.collection('license_customers').doc('_ws_agreement_settings').set(Object.assign({},s,{updatedAt:Date.now()}),{merge:true}).catch(()=>{});}}catch(e){}
    return s;}
};
skaGetSettings();setInterval(addFab,1800);setTimeout(addFab,500);
})();
